/* eslint-disable react/require-default-props */
import { X } from '@hexa-ui/icons';
import * as DialogPrimitive from '@radix-ui/react-dialog';
import React, { ElementRef, useImperativeHandle, useRef } from 'react';
import { FocusOutsideEvent, PointerDownOutsideEvent } from '@radix-ui/react-dismissable-layer';
import { styled, config } from '@hexa-ui/theme';
import { CSS } from '@stitches/react/types/css-util';
import {
  StyledDialogHeader,
  StyledDialogTitle,
  StyledDialogBody,
  StyledDialogActions,
  OverlayCSS,
  ContentCSS,
  StyledCloseButton,
  StyledCriticalLine,
} from '../utils/Dialog.styles';

const StyledOverlay = styled(DialogPrimitive.Overlay, OverlayCSS);
const StyledDialogContent = styled(DialogPrimitive.Content, ContentCSS);

export type DialogProps = React.ComponentProps<typeof DialogPrimitive.Root> & {
  variant?: 'overlay' | 'noOverlay' | 'bottomTray' | 'takeOver';
  destructive?: 'critical' | 'off';
  closeButton?: boolean;
  onClose?: (event: React.MouseEvent<HTMLButtonElement>) => void;
  onEscapeKeyDown?: (event: KeyboardEvent) => void;
  onPointerDownOutside?: (event: PointerDownOutsideEvent) => void;
  onInteractOutside?: (event: PointerDownOutsideEvent | FocusOutsideEvent) => void;
  headerImage?: React.ReactNode;
  headerHeight?: string;
  trigger?: React.ReactNode;
  title?: React.ReactNode;
  actions?: React.ReactNode;
  contentCss?: CSS<typeof config>;
};

type OverlayProps = React.ComponentProps<typeof DialogPrimitive.Overlay> & {
  color?: 'dark' | 'light';
};

const Overlay = ({ color = 'dark' }: OverlayProps): JSX.Element => <StyledOverlay color={color} />;

const { Trigger, Close } = DialogPrimitive;

export const DialogClose = ({ children }: { children: React.ReactNode }): JSX.Element => (
  <Close asChild>{children}</Close>
);

export const Dialog = React.forwardRef<ElementRef<typeof StyledDialogContent>, DialogProps>(
  (
    {
      children,
      variant = 'overlay',
      destructive = 'off',
      closeButton = true,
      onClose,
      onEscapeKeyDown,
      onPointerDownOutside,
      onInteractOutside,
      headerImage,
      headerHeight,
      title,
      actions,
      trigger,
      contentCss,
      ...props
    },
    forwardedRef
  ): JSX.Element => {
    const innerRef = useRef<HTMLDivElement>(null);
    useImperativeHandle(forwardedRef, () => innerRef?.current as HTMLDivElement);

    return (
      <DialogPrimitive.Root {...props} modal={variant !== 'noOverlay'}>
        {variant !== 'noOverlay' && <Overlay id="overlay" />}
        {trigger && <Trigger asChild>{trigger}</Trigger>}
        <StyledDialogContent
          onPointerDownOutside={onPointerDownOutside}
          onEscapeKeyDown={onEscapeKeyDown}
          onInteractOutside={onInteractOutside}
          variant={variant}
          ref={innerRef}
        >
          {destructive === 'critical' && <StyledCriticalLine data-testid="destructive" />}
          {(headerImage || title) && (
            <StyledDialogHeader
              image={Boolean(headerImage)}
              css={{ ...(headerHeight && { height: `${headerHeight}` }) }}
            >
              {headerImage}
              {title && (
                <StyledDialogTitle shouldAdjustPadding={!headerImage && closeButton}>
                  {title}
                </StyledDialogTitle>
              )}
            </StyledDialogHeader>
          )}
          <StyledDialogBody
            adjustTopPadding={!headerImage && !title}
            adjustRightPadding={!headerImage && !title && closeButton}
            css={contentCss}
          >
            {children}
          </StyledDialogBody>
          {actions && <StyledDialogActions>{actions}</StyledDialogActions>}
          {closeButton && (
            <Close onClick={onClose} asChild>
              <StyledCloseButton size="small" icon={X} variant="tertiary" />
            </Close>
          )}
        </StyledDialogContent>
      </DialogPrimitive.Root>
    );
  }
);
